using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions { TypeInfoResolver = new DefaultJsonTypeInfoResolver() };

// 1) Strongly-typed metadata — returns JsonTypeInfo<WeatherForecast> directly
JsonTypeInfo<WeatherForecast> typeInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got typed metadata for: {typeInfo.Type.Name}");
Console.WriteLine($"  Kind          : {typeInfo.Kind}");
Console.WriteLine($"  Properties    : {typeInfo.Properties.Count}");

// 2) Probe without throwing — TryGetTypeInfo<T> returns false instead of throwing
//    Use an empty resolver so nothing is resolvable.
var empty = new JsonSerializerOptions { TypeInfoResolver = JsonTypeInfoResolver.Combine() };

if (empty.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? probed))
    Console.WriteLine($"\nProbe succeeded: {probed.Type.Name}");
else
    Console.WriteLine("\nProbe returned false — no metadata available (no exception thrown)");

// A simple DTO for the demo
public record WeatherForecast(string City, double TempC, DateTime Date);

